const ids = ["2:24","2:29","2:34","2:45","4:11","3:59","3:62","3:65","3:68","3:71"];
const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out.push({id, missing:true}); continue; }
  const info = {id, name:n.name, type:n.type, w:n.width, h:n.height};
  if (n.type === "COMPONENT" || n.type === "INSTANCE") {
    info.children = n.children ? n.children.map(c=>({name:c.name,type:c.type,w:c.width,h:c.height, chars: c.type==="TEXT"?c.characters:undefined, fontName: c.type==="TEXT"?c.fontName:undefined, fontSize: c.type==="TEXT"?c.fontSize:undefined, fills: c.fills && c.fills[0] && c.fills[0].type})) : [];
    info.fills = n.fills;
    info.cornerRadius = n.cornerRadius;
    info.componentPropertyDefinitions = n.componentPropertyDefinitions;
  }
  out.push(info);
}
return JSON.stringify(out, null, 1);

