  disabled:{r:0.80,g:0.82,b:0.85}
};
const solid=(c,o)=>[{type:"SOLID",color:c,opacity:o===undefined?1:o}];
async function T(chars,size,style,color,opt){
  const t=figma.createText();
  t.fontName={family:"Montserrat",style:style||"Regular"};
  t.fontSize=size; t.characters=chars; t.fills=solid(color||C.ink);
  if(opt){ if(opt.w){t.textAutoResize="HEIGHT"; t.resize(opt.w,t.height);} if(opt.name)t.name=opt.name; if(opt.align)t.textAlignHorizontal=opt.align; if(opt.lh)t.lineHeight={value:opt.lh,unit:"PIXELS"}; }
  return t;
}
function frame(name,x,y,w,h,fill){
  const f=figma.createFrame(); f.name=name; f.x=x; f.y=y; if(w){f.resize(w,h);} f.fills=fill?solid(fill):[];
  return f;
}
function autoV(f,pad,gap){ f.layoutMode="VERTICAL"; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="FIXED"; f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=pad||0; f.itemSpacing=gap||0; }
function autoH(f,gap,align){ f.layoutMode="HORIZONTAL"; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO"; f.itemSpacing=gap||0; if(align)f.counterAxisAlignItems=align; }
function rect(w,h,fill,r){ const n=figma.createRectangle(); n.resize(w,h); n.fills=solid(fill); if(r!==undefined)n.cornerRadius=r; return n; }

const lib = frame("_LIB", 0, 3200, 10, 10); // container area for our components
lib.fills=[]; lib.resize(1200,10);

const ids = {};

// ---------- Icon helper component (recolorable wrapper) ----------
function makeIcon(name, srcId, size){
  const src = figma.getNodeByIdAsync ? null : null;
  return null;
}

// ---------- TabBar ----------
const tabIcons = {Home:"4:31", Wishlist:"4:36", Cart:"4:43", Search:"4:49", Setting:"4:55"};
async function buildTab(current){
  const bar = figma.createFrame(); bar.name="TabBar/"+current;
  bar.resize(375,60); bar.fills=solid(C.white);
  bar.strokes=solid(C.line); bar.strokeWeight=1; bar.strokeAlign="INSIDE";
  // only top border: use single stroke rect instead
  bar.strokes=[]; 
  const topLine = rect(375,1,C.line); topLine.x=0; topLine.y=0; bar.appendChild(topLine);
  autoH(bar,0,"CENTER"); bar.primaryAxisSizingMode="FIXED"; bar.counterAxisSizingMode="FIXED";
  bar.paddingLeft=8; bar.paddingRight=8; bar.paddingTop=8; bar.paddingBottom=6;
  const tabs=["Home","Wishlist","Cart","Search","Setting"];
  for(const t of tabs){
    const cell=figma.createFrame(); cell.name="Tab "+t; autoV(cell,0,4); cell.counterAxisAlignItems="CENTER"; cell.fills=[];
    cell.layoutGrow=1; cell.layoutAlign="STRETCH";
    const ic=(await figma.getNodeByIdAsync(tabIcons[t])).createInstance();
    ic.resize(24,24); ic.name="Icon";
    const col = t===current? C.brand : C.faint;
    ic.findAll(n=>"fills" in n && n.fills && n.fills.length>0 && n.type!=="FRAME" && n.type!=="INSTANCE").forEach(n=>{ try{n.fills=solid(col);}catch(e){} });
    cell.appendChild(ic);
    const lb=await T(t,10, t===current?"SemiBold":"Medium", t===current?C.brand:C.sub);
    lb.name="Label"; cell.appendChild(lb);
    bar.appendChild(cell);
  }
  return bar;
}
for(const cur of ["Home","Cart","Setting"]){
  const b=await buildTab(cur);
  const comp=figma.createComponentFromNode(b); comp.name="TabBar · "+cur; comp.description="Main navigation, current tab: "+cur;
  lib.appendChild(comp);
  ids["TabBar_"+cur]=comp.id;
}

