  const f=figma.createFrame(); f.name=name; f.resize(375,812); f.x=x; f.y=0; f.fills=solid(C.white); f.clipsContent=true;
  const sb=(await figma.getNodeByIdAsync("2:34")).createInstance(); sb.x=0; sb.y=0; sb.name="Status Bar"; f.appendChild(sb);
  const hi=(await figma.getNodeByIdAsync("2:45")).createInstance(); hi.x=0; hi.y=778; hi.name="Home Indicator"; f.appendChild(hi);
  return f;
}
async function primaryBtn(label,w){
  const b=(await figma.getNodeByIdAsync("2:24")).createInstance();
  b.setProperties({"Label#2:0":label});
  if(w){ b.resize(w,55); }
  b.name="Button/"+label;
  return b;
}
async function ghostBtn(label,w){
  const g=(await figma.getNodeByIdAsync("58:137")).createInstance();
  g.findOne(n=>n.name==="Label").characters=label;
  if(w) g.resize(w,48);
  g.name="Button/"+label;
  return g;
}
async function socialBtn(sid,nm,x,y){
  const sb=(await figma.getNodeByIdAsync("58:140")).createInstance(); sb.x=x; sb.y=y; sb.name="Social/"+nm;
  const slot=sb.findOne(n=>n.name==="LogoSlot"); slot.visible=false;
  const lg=(await figma.getNodeByIdAsync(sid)).createInstance(); lg.resize(24,24); lg.name=nm; lg.x=16; lg.y=16;
  sb.appendChild(lg);
  return sb;
}
