// ============ Onboarding ============
async function onboarding(name,x,step,mediaId,mediaW,title,body,mode){
  const f=await newScreen(name,x);
  const skip=await T("Skip",13,"SemiBold",C.sub); skip.name="Skip"; skip.x=327; skip.y=60; f.appendChild(skip);
  const m=(await figma.getNodeByIdAsync(mediaId)).createInstance();
  const mw=Math.round(mediaW);
  m.resize(mw,180); m.name="Illustration"; m.x=(375-mw)/2; m.y=150; f.appendChild(m);
  const st=(await figma.getNodeByIdAsync(step===1?"58:164":step===2?"58:169":"58:174")).createInstance();
  st.name="Progress · step "+step+" of 3"; st.x=(375-st.width)/2; st.y=380; f.appendChild(st);
  const stepLbl=await T("Step "+step+" of 3",11,"Medium",C.faint); stepLbl.x=(375-stepLbl.width)/2; stepLbl.y=400; f.appendChild(stepLbl);
  const t=await T(title,26,"Bold",C.ink,{align:"CENTER",w:311}); t.name="Title"; t.x=32; t.y=440; f.appendChild(t);
  const b=await T(body,14,"Regular",C.sub,{align:"CENTER",w:311,lh:22}); b.name="Body"; b.x=32; b.y=440+t.height+12; f.appendChild(b);
  const btnY=660;
  if(mode==="next"){
    const nb=await primaryBtn("Next",311); nb.x=32; nb.y=btnY; f.appendChild(nb);
  } else if(mode==="prevnext"){
    const pb=await ghostBtn("Prev",148); pb.x=32; pb.y=btnY+3; f.appendChild(pb);
    const nb=await primaryBtn("Next",148); nb.x=195; nb.y=btnY; f.appendChild(nb);
  } else {
    const pb=await ghostBtn("Prev",148); pb.x=32; pb.y=btnY+3; f.appendChild(pb);
    const nb=await primaryBtn("Get Started",148); nb.x=195; nb.y=btnY; f.appendChild(nb);
  }
  return f;
}
