async function T(chars,size,style,color,opt){
  const t=figma.createText(); t.fontName={family:"Montserrat",style:style||"Regular"};
  t.fontSize=size; t.characters=chars; t.fills=solid(color||C.ink);
  if(opt){ if(opt.w){t.textAutoResize="HEIGHT"; t.resize(opt.w,t.height);} if(opt.name)t.name=opt.name; if(opt.align)t.textAlignHorizontal=opt.align; if(opt.lh)t.lineHeight={value:opt.lh,unit:"PIXELS"}; }
  return t;
}
