async function buildTabBar(current){
  const comp = figma.createComponent();
  comp.name = "TabBar · "+current;
  comp.resize(375,78);
  comp.fills = solid(C.white);
  comp.layoutMode="VERTICAL";
  comp.primaryAxisSizingMode="FIXED";
  comp.counterAxisSizingMode="FIXED";
  comp.itemSpacing=0;
  comp.paddingTop=0;comp.paddingBottom=0;comp.paddingLeft=0;comp.paddingRight=0;
  // top border line
  const line = figma.createRectangle(); line.name="Top Line"; line.resize(375,1); line.fills=solid(C.line);
  comp.appendChild(line);
  // row of tabs
  const row = figma.createFrame(); row.name="Tabs"; row.layoutMode="HORIZONTAL"; row.fills=[];
  row.primaryAxisSizingMode="FIXED"; row.counterAxisSizingMode="AUTO";
  row.resize(375,56); row.itemSpacing=0; row.counterAxisAlignItems="CENTER";
  comp.appendChild(row);
  for(const tab of ["Home","Wishlist","Cart","Search","Setting"]){
    const t = figma.createFrame(); t.name="Tab "+tab;
    t.layoutMode="VERTICAL"; t.counterAxisAlignItems="CENTER"; t.itemSpacing=3;
    t.primaryAxisSizingMode="AUTO"; t.counterAxisSizingMode="FIXED";
    t.fills=[]; t.resize(75,50); t.layoutGrow=1; t.paddingTop=6;t.paddingBottom=4;
    row.appendChild(t);
    const ic = (await figma.getNodeByIdAsync(iconIds[tab])).createInstance();
    ic.resize(22,22); ic.name="Icon";
    const active = tab===current;
    const col = active?C.brand:C.faint;
    ic.findAll(n=>"fills" in n && n.fills && n.fills.length>0 && n.type!=="FRAME" && n.type!=="INSTANCE").forEach(n=>{try{n.fills=solid(col);}catch(e){}});
    t.appendChild(ic);
    const lbl = figma.createText(); lbl.fontName={family:"Montserrat",style:active?"SemiBold":"Medium"};
    lbl.fontSize=10; lbl.characters=tab; lbl.fills=solid(active?C.brand:C.faint); lbl.name="Label";
    t.appendChild(lbl);
  }
  // home indicator spacer area is separate; keep 78 total: 1 line + 56 tabs + 21 bottom
  const bottom = figma.createFrame(); bottom.name="Bottom Space"; bottom.resize(375,21); bottom.fills=[];
  comp.appendChild(bottom);
  return comp;
}

