const f = await figma.getNodeByIdAsync("88:296");
await figma.loadFontAsync({family:"Montserrat",style:"Medium"});
const sizes = ["6 UK","7 UK","8 UK","9 UK","10 UK"];
let x = 16;
for (const s of sizes) {
  const sel = s === "7 UK";
  const chip = figma.createFrame();
  chip.name = "SizeChip " + s;
  chip.layoutMode = "HORIZONTAL";
  chip.primaryAxisSizingMode = "AUTO";
  chip.counterAxisSizingMode = "AUTO";
  chip.paddingTop = 8; chip.paddingBottom = 8; chip.paddingLeft = 12; chip.paddingRight = 12;
  chip.cornerRadius = 8;
  chip.fills = sel ? [{type:"SOLID",color:{r:0.973,g:0.216,b:0.345}}] : [{type:"SOLID",color:{r:0.96,g:0.96,b:0.97}}];
  if (!sel) chip.strokes = [{type:"SOLID",color:{r:0.88,g:0.89,b:0.91}}], chip.strokeWeight = 1;
  f.appendChild(chip);
  chip.x = x; chip.y = 630;
  const t = figma.createText();
  t.fontName = {family:"Montserrat",style:"Medium"};
  t.characters = s;
  t.fontSize = 12;
  t.fills = [{type:"SOLID",color: sel ? {r:1,g:1,b:1} : {r:0.35,g:0.38,b:0.45}}];
  chip.appendChild(t);
  x += chip.width + 8;
}
return "chips ok, last x=" + x;

