function extent(id){return figma.getNodeByIdAsync(id).then(f=>{let max=0;for(const c of f.children){max=Math.max(max,c.y+c.height);}return {name:f.name,h:f.height,clips:f.clipsContent,extent:max,kids:f.children.map(c=>c.name+"@"+Math.round(c.y)+"+"+Math.round(c.height))};});}
const home = await extent("73:188");
const pl = await extent("79:245");
return JSON.stringify({home,pl});

function dump(n,d){const o={n:n.name,t:n.type[0],w:Math.round(n.width),h:Math.round(n.height)};
if(n.type==="TEXT"){o.c=n.characters;o.fs=n.fontSize;}
if(n.layoutMode&&n.layoutMode!=="NONE"){o.l=n.layoutMode[0];o.g=n.itemSpacing;o.pS=n.primaryAxisSizingMode[0];o.cS=n.counterAxisSizingMode[0];o.p=[n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft];}
if(d>0&&n.children)o.k=n.children.map(c=>dump(c,d-1));return o;}
